import pytest

from bedrock_protocol import nbt, v2225

# generated by gophertunnel b8bd735:
# packet.SyncActorProperty{PropertyData: map[string]any{"id": int32(7)}}
WITH_ID = bytes.fromhex("0a00030269640e00")

# generated by gophertunnel b8bd735:
# packet.SyncActorProperty{PropertyData: map[string]any{}}
EMPTY_TAG = bytes.fromhex("0a0000")

GOLDENS = [
    pytest.param(
        v2225.SyncActorPropertyPacket(property_data=nbt.CompoundTag({"id": nbt.IntTag(7)})),
        WITH_ID,
        id="with-id",
    ),
    pytest.param(v2225.SyncActorPropertyPacket(), EMPTY_TAG, id="empty-tag"),
]


@pytest.mark.parametrize(("packet", "golden"), GOLDENS)
def test_sync_actor_property_encodes_to_its_golden(packet, golden):
    assert bytes(packet) == golden


@pytest.mark.parametrize(("packet", "golden"), GOLDENS)
def test_sync_actor_property_decodes_from_its_golden(packet, golden):
    assert type(packet).from_bytes(golden) == packet
